# 1. prompts.csv (Gem用バッチ画像生成CSV)
prompts_csv_path = r'C:\Users\s8933\Downloads\PvPジョイナー動画\prompts.csv'
with open(prompts_csv_path, 'w', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['No', 'キャラ', '画像生成プロンプト'])
    for cut_id, char_name, gem_code, s_start, s_end, line_text, telop, prompt_desc in cuts_data:
        full_gem_prompt = f"{gem_code} {prompt_desc}"
        writer.writerow([cut_id, char_name, full_gem_prompt])

print(f"Generated {prompts_csv_path} ({len(cuts_data)} rows)")

# 2. chapter_sheet.csv (Google Sheets / スプレッドシート用CSV)
sheet_csv_path = r'C:\Users\s8933\Downloads\PvPジョイナー動画\chapter_sheet.csv'
with open(sheet_csv_path, 'w', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['No', '音声ファイル', 'キャラ', '開始(通し時間)', '終了(通し時間)', 'セリフ(該当区間)', '要約テロップ', '画像生成プロンプト'])
    for cut_id, char_name, gem_code, s_start, s_end, line_text, telop, prompt_desc in cuts_data:
        audio_name = f"{cut_id}_{char_name}_音声.wav"
        m_start, sec_start = divmod(int(s_start), 60)
        m_end, sec_end = divmod(int(s_end), 60)
        start_str = f"{m_start}分{sec_start:02d}秒"
        end_str = f"{m_end}分{sec_end:02d}秒"
        full_gem_prompt = f"{gem_code} {prompt_desc}"
        writer.writerow([cut_id, audio_name, char_name, start_str, end_str, line_text, telop, full_gem_prompt])

print(f"Generated {sheet_csv_path}")

# 3. script_full_timeline.md (完全版マークダウン台本)
md_path = r'C:\Users\s8933\Downloads\PvPジョイナー動画\script_full_timeline.md'
with open(md_path, 'w', encoding='utf-8') as f:
    f.write("# 【完全版台本＆演出時間割】キングスショットPvPジョイナー最強＆最弱Tier表\n\n")
    f.write(f"- 総カット数: {len(cuts_data)} カット\n")
    f.write("- 想定総再生時間: 10分14秒 (614秒)\n")
    f.write("- 配布Webサイト: `web_tierlist/index.html` (スマホ完全対応・乗算計算機付き)\n\n")
    f.write("---\n\n")
    for cut_id, char_name, gem_code, s_start, s_end, line_text, telop, prompt_desc in cuts_data:
        m_start, sec_start = divmod(int(s_start), 60)
        m_end, sec_end = divmod(int(s_end), 60)
        f.write(f"### 🎬 Cut {cut_id} 【{char_name}】 ({m_start}:{sec_start:02d} 〜 {m_end}:{sec_end:02d})\n")
        f.write(f"> **セリフ:** {line_text}\n\n")
        f.write(f"- **テロップ:** `{telop}`\n")
        f.write(f"- **画像プロンプト:** `{gem_code} {prompt_desc}`\n\n")

print(f"Generated {md_path}")
